'use client';

import { useLayoutEffect, useRef, type ReactNode } from 'react';
import { cx } from '@/utils/cx';

const layoutProperties = new Set([
  'height', 'block-size', 'min-height', 'max-height', 'min-block-size', 'max-block-size',
  'width', 'inline-size', 'min-width', 'max-width', 'min-inline-size', 'max-inline-size',
  'padding-top', 'padding-bottom', 'padding-left', 'padding-right', 'padding-block-start', 'padding-block-end',
  'margin-top', 'margin-bottom', 'margin-left', 'margin-right', 'margin-block-start', 'margin-block-end',
  'border-top-width', 'border-bottom-width', 'gap', 'row-gap', 'column-gap', 'grid-template-rows', 'grid-template-columns', 'flex-basis', 'font-size', 'line-height', 'letter-spacing',
]);

/** Animate real layout height so adjacent content follows without being scaled. */
export function AnimatedHeight({ children, className }: { children: ReactNode; className?: string }) {
  const frameRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const frame = frameRef.current;
    const content = contentRef.current;
    if (!frame || !content) return;
    // Start at the natural size, including when server-rendered content is nonempty.
    frame.style.transition = 'none';
    frame.style.height = `${content.offsetHeight}px`;
    void frame.offsetHeight;
    frame.style.removeProperty('transition');
    let alive = true;
    const observed = new WeakSet<Animation>();
    const affectsLayout = (animation: Animation) => {
      if (animation.playState !== 'running') return false;
      if ('transitionProperty' in animation) return layoutProperties.has(String(animation.transitionProperty));
      return animation.effect instanceof KeyframeEffect && animation.effect.getKeyframes().some(frame =>
        Object.keys(frame).some(property => layoutProperties.has(property.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`)))
      );
    };
    const nestedLayoutIsMoving = () => content.getAnimations({subtree: true}).some(affectsLayout);
    const restore = () => { if (alive && !nestedLayoutIsMoving()) frame.style.removeProperty('transition'); };
    const observeMotion = () => {
      const moving = content.getAnimations({subtree: true}).filter(affectsLayout);
      for (const animation of moving) if (!observed.has(animation)) {
        observed.add(animation);
        animation.finished.then(restore, restore);
      }
      return moving.length > 0;
    };
    const restoreTransition = (event: TransitionEvent) => {
      if (layoutProperties.has(event.propertyName)) restore();
    };
    content.addEventListener('transitionend', restoreTransition);
    content.addEventListener('transitioncancel', restoreTransition);
    const observer = new ResizeObserver(([entry]) => {
      const height = entry.borderBoxSize?.[0]?.blockSize ?? content.offsetHeight;
      // A child can already be animating its real height. Follow that geometry
      // directly, so nested frames do not each add another full transition.
      const following = observeMotion();
      if (following) frame.style.transition = 'none';
      else frame.style.removeProperty('transition');
      frame.style.height = `${height}px`;
    });
    // Helper text and disclosure spacing can change without changing the
    // content box. Observe the same border box that supplies the target height.
    observer.observe(content, { box: 'border-box' });
    return () => {
      alive = false;
      observer.disconnect();
      content.removeEventListener('transitionend', restoreTransition);
      content.removeEventListener('transitioncancel', restoreTransition);
    };
  }, []);
  return <div ref={frameRef} className={cx('ui-animated-height', className)}><div ref={contentRef} className="ui-animated-height__content">{children}</div></div>;
}

'use client';

import type { ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';
import { Spinner } from '@/components/base/spinner/spinner';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'soft' | 'outline' | 'solid' | 'quiet';
export type ButtonSize = 'medium' | 'small' | 'xs';

type NativeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;
type ContentProps =
  | { iconOnly: true; 'aria-label': string; leadingIcon: IconComponent; children?: never }
  | { iconOnly?: false; children: ReactNode; leadingIcon?: IconComponent };

export type ButtonProps = NativeButtonProps & ContentProps & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  trailingIcon?: IconComponent;
  isLoading?: boolean;
  loadingLabel?: string;
  ref?: Ref<HTMLButtonElement>;
};

const base = 'ui-button inline-flex shrink-0 items-center justify-center whitespace-nowrap select-none outline-none';
const sizes: Record<ButtonSize, string> = {
  medium: 'h-9 rounded-[10px] px-2 gap-0.5',
  small: 'h-8 rounded-lg px-2 gap-0.5',
  xs: 'h-6 rounded-[5px] px-2 gap-0.5',
};
export const buttonIconClassNames: Record<ButtonSize, string> = { medium: 'size-5', small: 'size-[18px]', xs: 'size-3.5' };
export function buttonClassNames(size: ButtonSize, iconOnly = false, className?: string) {
  return cx(base, sizes[size], iconOnly && 'ui-button--icon-only !p-0', className);
}

export function Button({
  variant = 'primary',
  size = 'medium',
  iconOnly = false,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  children,
  className,
  type = 'button',
  isLoading = false,
  loadingLabel,
  disabled,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={isLoading && type === 'submit' ? 'button' : type}
      disabled={disabled}
      aria-disabled={isLoading || props['aria-disabled'] || undefined}
      aria-busy={isLoading || undefined}
      aria-description={isLoading && loadingLabel ? loadingLabel : props['aria-description']}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      data-loading={isLoading || undefined}
      data-loading-label={loadingLabel !== undefined || undefined}
      className={buttonClassNames(size, iconOnly, className)}
      onClick={event => { if (isLoading || props['aria-disabled'] === true || props['aria-disabled'] === 'true') { event.preventDefault(); event.stopPropagation(); return; } onClick?.(event); }}
      onKeyDown={event => { if (isLoading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); return; } onKeyDown?.(event); }}
    >
      {LeadingIcon && <span className="ui-button__leading-slot" aria-hidden><LeadingIcon className={cx(buttonIconClassNames[size], 'ui-button__leading-icon')}/></span>}
      {!iconOnly && <span className="ui-button__label">{children}</span>}
      {!iconOnly && TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
      <Spinner className="ui-button__busy-spinner" size={size === 'xs' ? 'xs' : size === 'small' ? 'sm' : 'md'}/>
    </button>
  );
}

import type { ButtonHTMLAttributes, Ref } from 'react';
import { cx } from '@/utils/cx';

export type CloseButtonSize = '2xs' | 'xs' | 'sm' | 'md';

export type CloseButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label'> & {
  size?: CloseButtonSize;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

const glyphSizes: Record<CloseButtonSize, number> = { '2xs': 8, xs: 11, sm: 13, md: 17 };
const strokes: Record<CloseButtonSize, number> = { '2xs': 1.6, xs: 2, sm: 2, md: 2.5 };

export function CloseButton({ size = 'xs', className, type = 'button', ...props }: CloseButtonProps) {
  const glyph = glyphSizes[size];
  const inset = size === '2xs' ? 1.4 : 2;
  return (
    <button type={type} data-size={size} className={cx('ui-close-button', className)} {...props}>
      <svg width={glyph} height={glyph} viewBox={`0 0 ${glyph} ${glyph}`} fill="none" aria-hidden="true">
        <path d={`M${inset} ${inset}L${glyph - inset} ${glyph - inset}M${glyph - inset} ${inset}L${inset} ${glyph - inset}`} stroke="currentColor" strokeWidth={strokes[size]} strokeLinecap="round" />
      </svg>
    </button>
  );
}

'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { cx } from '@/utils/cx';

export type CardProps = HTMLAttributes<HTMLDivElement> & { ref?: Ref<HTMLDivElement>; variant?: 'bordered' | 'raised' | 'soft'; padding?: 'none' | 'small' | 'medium' | 'large' };
export function Card({ variant = 'bordered', padding = 'medium', className, ...props }: CardProps) {
  return <div {...props} className={cx('ui-card', className)} data-variant={variant} data-padding={padding}/>;
}
export function CardHeader({ title, description, actions, leading }: { title: string; description?: string; actions?: ReactNode; leading?: ReactNode }) {
  return <header className="ui-card__header">{leading && <span className="ui-card__leading" aria-hidden>{leading}</span>}<div><h3>{title}</h3>{description && <p>{description}</p>}</div>{actions && <div className="ui-card__actions">{actions}</div>}</header>;
}
export function CardFooter({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div {...props} className={cx('ui-card__footer', className)}/>; }

import type { HTMLAttributes, ReactNode } from 'react';
import { cx } from '@/utils/cx';

export type CollapsibleProps = Omit<HTMLAttributes<HTMLDivElement>, 'children'> & { isOpen: boolean; children: ReactNode };

/** Keep descendants mounted while hiding their focus targets and animating flow. */
export function Collapsible({ isOpen, children, className, ...props }: CollapsibleProps) {
  return <div {...props} className={cx('ui-collapsible', className)} data-open={isOpen || undefined} aria-hidden={!isOpen} inert={!isOpen}>
    <div className="ui-collapsible__inner"><div className="ui-collapsible__content">{children}</div></div>
  </div>;
}

import type { ReactNode } from 'react';
import { cx } from '@/utils/cx';

export type EmptyStateProps = {
  title: string;
  description?: ReactNode;
  icon?: ReactNode;
  actions?: ReactNode;
  children?: ReactNode;
  size?: 'small' | 'medium' | 'large';
  variant?: 'plain' | 'bordered' | 'soft';
  className?: string;
};

export function EmptyState({ title, description, icon, actions, children, size = 'medium', variant = 'plain', className }: EmptyStateProps) {
  return <div className={cx('ui-empty-state', className)} data-size={size} data-variant={variant}>
    {icon && <div className="ui-empty-state__icon" aria-hidden>{icon}</div>}<h3>{title}</h3>{description && <p>{description}</p>}{actions && <div className="ui-empty-state__actions">{actions}</div>}{children && <div className="ui-empty-state__detail">{children}</div>}
  </div>;
}

'use client';

import {createContext, useContext} from 'react';

export const FieldSetDisabledContext = createContext(false);

/** An individual control cannot re-enable itself inside a disabled fieldset. */
export function useFieldDisabled(disabled?: boolean) {
  return useContext(FieldSetDisabledContext) || disabled;
}

'use client';

import { useContext, useLayoutEffect, useRef, useState } from 'react';
import { FieldError, FieldErrorContext, Text } from 'react-aria-components';
import { AnimatePresence, motion, useIsPresent, useReducedMotion } from 'motion/react';
import { AnimatedHeight } from '@/components/base/animated-height/animated-height';

function ErrorContent({ error }: { error?: string }) {
  const present = useIsPresent();
  const element = useRef<HTMLElement>(null);
  const [snapshot, setSnapshot] = useState(error ?? '');
  useLayoutEffect(() => {
    if (present && element.current) {
      const text = element.current.textContent ?? '';
      setSnapshot(previous => previous === text ? previous : text);
    }
  });
  return <div className="ui-field-feedback__error" inert={!present} aria-hidden={!present || undefined}>
    {present ? <FieldError ref={element} className="ui-input-field__message">{error}</FieldError> : <span className="ui-input-field__message">{snapshot}</span>}
  </div>;
}

/** Keep native validation messages associated while animating their actual layout. */
export function FieldFeedback({ hint, error }: { hint?: string; error?: string }) {
  const validation = useContext(FieldErrorContext);
  const reduced = useReducedMotion();
  const invalid = validation?.isInvalid ?? Boolean(error);
  const showHint = Boolean(hint && !error);
  return <div className="ui-field-feedback" data-content={invalid || showHint || undefined}>
    <AnimatedHeight>
      {showHint && <Text slot="description" className="ui-input-field__message">{hint}</Text>}
      <AnimatePresence initial={false} mode="popLayout">
        {invalid && <motion.div key="error" initial={{ opacity: 0, y: reduced ? 0 : 2 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: reduced ? 0 : -2 }} transition={{ duration: reduced ? 0 : .16, ease: [.2, .75, .25, 1] }}>
          <ErrorContent error={error}/>
        </motion.div>}
      </AnimatePresence>
    </AnimatedHeight>
  </div>;
}

'use client';

import type { AriaAttributes, ReactNode, Ref } from 'react';
import { TextField, Label, Input as AriaInput, type TextFieldProps } from 'react-aria-components';
import { cx } from '@/utils/cx';
import { FieldFeedback } from '@/components/base/input/field-feedback';
import { useFieldDisabled } from '@/components/base/field/field-context';

export type InputProps = Omit<TextFieldProps, 'children' | 'className'> & {
  'aria-busy'?: AriaAttributes['aria-busy'];
  label: string;
  placeholder?: string;
  hint?: string;
  error?: string;
  leading?: ReactNode;
  trailing?: ReactNode;
  trailingAction?: ReactNode;
  leadingAction?: ReactNode;
  blockStart?: ReactNode;
  blockEnd?: ReactNode;
  className?: string;
  hideLabel?: boolean;
  inputRef?: Ref<HTMLInputElement>;
  variant?: 'default' | 'plain' | 'soft';
  size?: 'small' | 'medium' | 'large';
  maxLength?: number;
};

export function Input({ label, placeholder, hint, error, leading, trailing, trailingAction, leadingAction, blockStart, blockEnd, className, isInvalid, hideLabel = false, inputRef, variant = 'default', size = 'medium', maxLength, ...props }: InputProps) {
  const isDisabled = useFieldDisabled(props.isDisabled);
  const stacked = blockStart !== undefined || blockEnd !== undefined;
  const control = <>{leadingAction && <span className="ui-input-field__action">{leadingAction}</span>}{leading && <span className="ui-input-field__adornment" aria-hidden="true">{leading}</span>}<AriaInput ref={inputRef} maxLength={maxLength} aria-busy={props['aria-busy']} className="ui-input-field__input" placeholder={placeholder} />{trailing && <span className="ui-input-field__adornment" aria-hidden="true">{trailing}</span>}{trailingAction && <span className="ui-input-field__action">{trailingAction}</span>}</>;
  return <TextField {...props} isDisabled={isDisabled} data-variant={variant} data-size={size} isInvalid={error ? true : isInvalid} className={cx('ui-input-field', className)}>
    <Label className={cx('ui-input-field__label', hideLabel && 'sr-only')}>{label}{props.isRequired && <span aria-hidden="true">*</span>}</Label>
    <div className={cx('ui-input-field__control', stacked && 'ui-input-field__control--stacked')}>{blockStart !== undefined && <div className="ui-input-group__block" data-align="start">{blockStart}</div>}{stacked ? <div className="ui-input-field__row">{control}</div> : control}{blockEnd !== undefined && <div className="ui-input-group__block" data-align="end">{blockEnd}</div>}</div>
    <FieldFeedback hint={hint} error={error}/>
  </TextField>;
}

'use client';

import { useCallback, useLayoutEffect, useRef, useState, type ReactElement, type ReactNode, type Ref, type RefObject } from 'react';
import { RiArrowDownSLine, RiArrowUpSLine, RiArrowLeftSLine, RiArrowRightSLine } from '@remixicon/react';
import { IconButton } from '@/components/base/buttons/icon-button';
import { cx } from '@/utils/cx';

export type ScrollAreaViewportProps = { ref: Ref<HTMLDivElement>; className: string; children: ReactNode };
export type ScrollAreaProps = {
  children?: ReactNode;
  label: string;
  className?: string;
  viewportClassName?: string;
  orientation?: 'vertical' | 'horizontal' | 'both';
  /** Let a collection own the scroll viewport, keeping its keyboard scrolling native. */
  renderViewport?: (props: ScrollAreaViewportProps) => ReactElement;
  /** Keep a pointer action in a searchable input without stealing its focus. */
  preservePointerFocus?: boolean;
  /** Restore a virtual collection's input when a focused edge disappears. */
  focusRef?: RefObject<HTMLElement | null>;
  /** Keep arrow controls outside the item viewport in constrained collections. */
  indicatorPlacement?: 'overlay' | 'gutter';
};

/** Keep native scrolling, with directional controls only when content overflows. */
export function ScrollArea({ children, label, className, viewportClassName, renderViewport, orientation = 'vertical', preservePointerFocus = false, focusRef, indicatorPlacement='overlay' }: ScrollAreaProps) {
  const viewport = useRef<HTMLDivElement>(null), content = useRef<HTMLDivElement>(null);
  const [mountedViewport, setMountedViewport] = useState<HTMLDivElement | null>(null);
  const setViewport = useCallback((element: HTMLDivElement | null) => {
    viewport.current = element;
    setMountedViewport(element);
  }, []);
  const [edges, setEdges] = useState({ up: false, down: false, left: false, right: false });
  const measuredEdges = useRef(edges);
  useLayoutEffect(() => {
    const el = mountedViewport;
    if (!el) return;
    function measure() {
      if (!el) return;
      const up = orientation !== 'horizontal' && el.scrollTop > 1, down = orientation !== 'horizontal' && el.scrollHeight - el.clientHeight - el.scrollTop > 1;
      const rtl = getComputedStyle(el).direction === 'rtl', maximum = el.scrollWidth - el.clientWidth;
      const left = orientation !== 'vertical' && (rtl ? maximum + el.scrollLeft : el.scrollLeft) > 1;
      const right = orientation !== 'vertical' && (rtl ? -el.scrollLeft : maximum - el.scrollLeft) > 1;
      const next = { up, down, left, right };
      const focusedEdge = document.activeElement?.closest('.ui-scroll-area__edge');
      const direction = focusedEdge?.getAttribute('data-direction') as keyof typeof next | undefined;
      if (focusedEdge && el.parentElement?.contains(focusedEdge) && direction && !next[direction]) (focusRef?.current ?? el).focus({ preventScroll: true });
      if (Object.keys(next).some(key => measuredEdges.current[key as keyof typeof next] !== next[key as keyof typeof next])) {
        measuredEdges.current = next;
        setEdges(measuredEdges.current);
      }
    }
    const observer = new ResizeObserver(measure);
    const observed = new Set<Element>();
    function observeContent() {
      if (!el) return;
      // A collection may not allow a wrapper between itself and its sections.
      // Observe those sections directly so filtering and density changes are measured.
      const next = new Set<Element>([el, ...el.children]);
      for (const child of observed) if (!next.has(child)) { observer.unobserve(child); observed.delete(child); }
      for (const child of next) if (!observed.has(child)) { observer.observe(child); observed.add(child); }
      measure();
    }
    const mutations = new MutationObserver(observeContent);
    mutations.observe(el, { childList: true, subtree: true });
    observeContent();
    el.addEventListener('scroll', measure, { passive: true });
    return () => { observer.disconnect(); mutations.disconnect(); el.removeEventListener('scroll', measure); };
  }, [focusRef, mountedViewport, orientation]);
  function scroll(direction: number, horizontal = false) {
    const el = viewport.current;
    if (!el) return;
    el.scrollBy({ [horizontal ? 'left' : 'top']: direction * Math.max(80, (horizontal ? el.clientWidth : el.clientHeight) * .7), behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
  }
  return <div className={cx('ui-scroll-area', className)} data-orientation={orientation} data-indicator-placement={indicatorPlacement} data-overflow-y={edges.up || edges.down || undefined}>
    {renderViewport ? renderViewport({ ref: setViewport, className: cx('ui-scroll-area__viewport', viewportClassName), children }) : <div ref={setViewport} className={cx('ui-scroll-area__viewport', viewportClassName)} role="region" aria-label={label} tabIndex={0}><div ref={content} className="ui-scroll-area__content">{children}</div></div>}
    <div className="ui-scroll-area__edge" data-direction="up" data-visible={edges.up || undefined} aria-hidden={!edges.up}><IconButton icon={RiArrowUpSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} up`} disabled={!edges.up} tabIndex={edges.up ? 0 : -1} onClick={() => scroll(-1)}/></div>
    <div className="ui-scroll-area__edge" data-direction="down" data-visible={edges.down || undefined} aria-hidden={!edges.down}><IconButton icon={RiArrowDownSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} down`} disabled={!edges.down} tabIndex={edges.down ? 0 : -1} onClick={() => scroll(1)}/></div>
    {orientation !== 'vertical' && <>
      <div className="ui-scroll-area__edge" data-direction="left" data-visible={edges.left || undefined} aria-hidden={!edges.left}><IconButton icon={RiArrowLeftSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} left`} disabled={!edges.left} tabIndex={edges.left ? 0 : -1} onClick={() => scroll(-1, true)}/></div>
      <div className="ui-scroll-area__edge" data-direction="right" data-visible={edges.right || undefined} aria-hidden={!edges.right}><IconButton icon={RiArrowRightSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} right`} disabled={!edges.right} tabIndex={edges.right ? 0 : -1} onClick={() => scroll(1, true)}/></div>
    </>}
  </div>;
}

'use client';

import { useImperativeHandle, useRef, useState, type Ref } from 'react';
import { RiSearchLine } from '@remixicon/react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { Input, type InputProps } from '@/components/base/input/input';
import { CloseButton } from '@/components/base/buttons/close-button';
import { Spinner } from '@/components/base/spinner/spinner';
import { cx } from '@/utils/cx';

export type SearchFieldProps = Omit<InputProps,'type'|'leading'|'trailing'|'trailingAction'|'inputRef'> & {isLoading?:boolean;onClear?:()=>void;inputRef?:Ref<HTMLInputElement>;};
export function SearchField({value,defaultValue='',onChange,onClear,isLoading=false,className,isDisabled,inputRef,...props}:SearchFieldProps) {
  const [internal,setInternal]=useState(defaultValue),text=value??internal,input=useRef<HTMLInputElement>(null);
  const reduced = useReducedMotion();
